        const auto child=[&](std::string_view slot,float scale=1.f){return sequence(value.GetNamedObject(wide(slot)),size*scale,child_path(path,index,slot),depth+1);};
        const auto optional=[&](std::string_view slot,float scale)->std::optional<Box>{return value.HasKey(wide(slot))?std::optional<Box>(child(slot,scale)):std::nullopt;};
        if(type=="sequence")return sequence(value,size,child_path(path,index,"content"),depth+1);
